usage() {
  cat <<USAGE
Usage: bootstrap.sh --list
       bootstrap.sh --stage <name>
       bootstrap.sh --stage <name> --apply --plan-digest <digest> [--rotate-token]
       bootstrap.sh --reset <KEY> | --help

  --list          The stages and their class (read or write). Static; needs nothing.
  --stage <name>  A READ stage runs. A WRITE stage prints its PLAN (what it would
                  change, in plain words, and the exact apply command) and changes nothing.
  --apply         With --stage <name> --plan-digest <digest>: perform the write. The
                  person approves the exact command at the harness prompt first.
  --plan-digest   The digest the plan printed. The script recomputes the plan; a
                  mismatch (the state moved) exits 75 and writes nothing.
  --reset <KEY>   Forget a persisted .env value so the next run re-asks for it.
  --help          This text.

There is no run-all mode and no flag that approves a write by itself.

Environment:
  SOLEUR_BOOTSTRAP_LEDGER=<path>     Run ledger (default: beside this script).
  SOLEUR_OP_LIB=<abs-path>           Override the library path baked at generation.

Skip variables — one per class-1/class-3 prompt in THIS script, derived from
its source so the list cannot drift (naming convention: SOLEUR_BOOTSTRAP_<WHAT>
for a value, SOLEUR_BOOTSTRAP_SKIP_<WHAT>_BARRIER for a barrier):
$(grep -oE '^[[:space:]]*soleur_op_(barrier|value) SOLEUR_BOOTSTRAP_[A-Z0-9_]+' "${BASH_SOURCE[0]}" | awk '{print "  " $2}' | sort -u | grep . || echo '  (none: this script has no class-1 or class-3 prompt)')
USAGE
}

# --- argument validation -----------------------------------------------------
# Deliberately ABOVE the EXIT trap installed below: a usage error must print no
# "Stopped during stage" banner, and `--reset` is not a stage. ORIG_ARGV keeps the
# invocation exactly as the shell handed it over: the approval receipt is bound to
# it (so `"a b"` and `"a" "b"` differ).
ORIG_ARGV=("$@")
STAGE=""
APPLY=0
PLAN_DIGEST=""
ROTATE_TOKEN=0
RESET_KEY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --stage) STAGE="${2:-}"; [[ -n "$STAGE" ]] || { echo "Error: --stage needs a stage name (--list shows them)" >&2; usage >&2; exit 1; }; shift 2 ;;
    --apply) APPLY=1; shift ;;
    --plan-digest) PLAN_DIGEST="${2:-}"; [[ -n "$PLAN_DIGEST" ]] || { echo "Error: --plan-digest needs the digest the plan printed" >&2; usage >&2; exit 1; }; shift 2 ;;
    --rotate-token) ROTATE_TOKEN=1; shift ;;
    --reset) RESET_KEY="${2:-}"; [[ -n "$RESET_KEY" ]] || { echo "Error: --reset needs a KEY" >&2; usage >&2; exit 1; }; shift 2 ;;
    --list) soleur_op_list "${BASH_SOURCE[0]}"; exit 0 ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; usage >&2; exit 1 ;;
  esac
done

# --- the credentials file must be ignored by git ------------------------------
# This script lives in a TRACKED directory (SKILL.md §Where), and its .env holds
# recorded values. A .gitignore that does not cover it turns the founder's next
# `git add .` into a pushed token (review P1-1). Checked BEFORE the first write —
# `--reset` writes too — on the .env AND on the `.tmp.XXXXXX` sibling the upsert
# creates beside it, which a bare `.env` pattern does not cover. Outside a git
# work tree (or without git) there is nothing to commit, so the check passes.
#
# PROBE THE RESOLVED PATH — the writer does. `soleur_op_env_upsert` and
# `soleur_op_env_reset` both `readlink -f` before writing, so probing the link
# NAME asks git about a file the write never touches: a founder who symlinks
# .env at a shared credentials file gets an ignored name, a passing probe, and
# the value written to a target git reports as untracked-and-not-ignored. The
# `.tmp.XXXXXX` sibling is created beside the RESOLVED file too, so it is
# derived from the resolved path rather than from $ENV_FILE. Confirmed against
# a fixture; Guard 7's symlink rows pin it.
env_not_ignored() {
  local dir; dir="$(dirname "$1")"
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 1
  ! git -C "$dir" check-ignore -q "$1"
}
ENV_FILE_RESOLVED="$(readlink -f -- "$ENV_FILE" 2>/dev/null || printf '%s' "$ENV_FILE")"
for probe in "$ENV_FILE_RESOLVED" "${ENV_FILE_RESOLVED}.tmp.XXXXXX"; do
  if env_not_ignored "$probe"; then
    printf 'SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED path=%s\n' "$probe"
    printf 'The credentials file would be committed. Add it to .gitignore first (a pattern such as .env* covers both the file and its temp sibling).\n'
    exit 64
  fi
done
unset probe

if [[ -n "$RESET_KEY" ]]; then
  soleur_op_env_reset "$ENV_FILE" "$RESET_KEY"
  soleur_op_green "Forgot ${RESET_KEY}. Re-run the stage to be asked for it again."
  exit 0
fi

if [[ -z "$STAGE" ]]; then
  printf 'SOLEUR_BOOTSTRAP_STAGE_REQUIRED\n'
  printf 'Pick one stage with --stage <name>; this script has no run-all mode. The stages are:\n'
  soleur_op_list "${BASH_SOURCE[0]}"
  exit 64
fi

# --- terminal outcome --------------------------------------------------------
# ONE trap. On a non-zero exit inside a stage it prints the STAGE_FAILED marker,
# tells the founder which stage stopped and the one command that resumes, and
# settles the stage in the ledger as `failed`. A refusal that already printed its
# own marker and sentence (approval required / invalid / plan drift, a precondition,
# a missing digest) raised the library's SOLEUR_OP_REFUSED flag and settles as
# `refused`, adding nothing. The flag, not the exit code, decides: a vendor CLI that
# exits 75 mid-write is a failure.
SCRIPT_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
SCRIPT_REAL="$(soleur_approval_realpath "${BASH_SOURCE[0]}")"
CURRENT_STAGE_INDEX=0
CURRENT_STAGE_NAME=""
STAGE_CHANGED=""
mark_changed() { STAGE_CHANGED="${STAGE_CHANGED:+${STAGE_CHANGED}; }$1"; }
on_exit() {
  local rc=$?
  [[ "$rc" -ne 0 && "$CURRENT_STAGE_INDEX" -gt 0 ]] || return 0
  if [[ -n "${SOLEUR_OP_REFUSED:-}" ]]; then
    soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" refused "$rc"
    return 0
  fi
  printf 'SOLEUR_BOOTSTRAP_STAGE_FAILED stage=%s rc=%s\n' "$CURRENT_STAGE_NAME" "$rc"
  # "Nothing else was changed" is FALSE on one path the library documents: a
  # secret whose write returned 0 and whose read-back did not confirm it may be
  # live (SOLEUR_BOOTSTRAP_SECRET_VERIFY_FAILED). The library raises a flag and
  # this sentence defers to it.
  if [[ -n "${SOLEUR_OP_WRITE_MAY_HAVE_LANDED:-}" ]]; then
    printf 'Stopped during stage %s. A credential may already have been written — check it and revoke it if you did not mean to. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  elif [[ -n "$STAGE_CHANGED" ]]; then
    printf 'Stopped during stage %s AFTER it may have changed production: %s. Read the lines above before re-running. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$STAGE_CHANGED" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  else
    printf 'Stopped during stage %s. Nothing else was changed. Run the stage again: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  fi
  soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" failed "$rc"
}
trap on_exit EXIT

# =============================================================================
# STAGES — everything below this line is yours. Replace the examples.
# =============================================================================
#
# For each stage declared in the table above:
#   read stage   read_<name>()   precondition-free: it only READS and reports.
#   write stage  plan_<name>()   READ-ONLY. Calls `soleur_op_plan_op <op> <target>`
#                                once per change it WOULD make, naming operations
#                                and targets only (never a value). A stage that is
#                                already satisfied declares NO operation: it then
#                                needs no approval and `--apply` changes nothing.
#                                If a precondition (an earlier stage's work) does
#                                not hold, call `soleur_op_precondition_failed
#                                <stage> <need-stage> "<sentence>"`: stages are
#                                separately addressable, so each re-proves what it
#                                depends on instead of trusting that another ran.
#                apply_<name>()  the writes. It runs ONLY after the gate returned,
#                                i.e. after the human approved the exact command.
# Function names replace `-` in the stage name with `_`.
#
# NEVER call `soleur_op_ack_or_die` here: it needs a typed `yes` at a terminal and
# makes the stage unrunnable by an agent. The gate is `soleur_op_stage_gate`, called
# by the dispatcher below, not by your stage.
#
# The library sets `umask 077`, and every child a stage starts INHERITS it: a
# file a stage writes for someone else (a public key, a config the vendor CLI
# reads) lands 0600. Escape per command, never globally:
#   (umask 022; printf '%s\n' "$pubkey" > "$HOME/.ssh/id.pub")

# --- helpers ------------------------------------------------------------------
env_get() {  # .env read — never echoes a secret NAME's value it shouldn't (names only)
  [[ -f "$ENV_FILE" ]] && grep -a "^$1=" "$ENV_FILE" | tail -1 | cut -d= -f2-
  return 0
}

fp_of_pem_file() {  # sha256[:8] of the value $1 holds modulo a trailing newline —
  local v                       # the $() capture mirrors what the probe sees in env
  v="$(cat "$1" 2>/dev/null)" || { echo ""; return 0; }
  printf '%s' "$v" | openssl dgst -sha256 | awk '{print $NF}' | cut -c1-8
}

fp_of_secret() {  # fp of the VALUE stored at $1/$2 secret $3 (trailing-newline-free), or empty
  local v
  v="$(doppler secrets get "$3" -p "$1" -c "$2" --plain 2>/dev/null)" || { echo ""; return 0; }
  printf '%s' "$v" | openssl dgst -sha256 | awk '{print $NF}' | cut -c1-8
}

installed_app() {  # prints "installation_id app_id" for the fixture app, or empty
  gh api "/orgs/${ORG}/installations" --paginate \
    --jq ".installations[] | select(.app_slug==\"${APP_SLUG}\") | \"\\(.id) \\(.app_id)\"" 2>/dev/null \
    | head -1
}

# =============================================================================
# preflight (read): tools + auth + the current (dead) credential fingerprint.
# =============================================================================
read_preflight() {
  local bad=0
  command -v gh      >/dev/null 2>&1 || { soleur_op_red "  gh not on PATH"; bad=1; }
  command -v doppler >/dev/null 2>&1 || { soleur_op_red "  doppler not on PATH"; bad=1; }
  command -v openssl >/dev/null 2>&1 || { soleur_op_red "  openssl not on PATH"; bad=1; }
  command -v jq      >/dev/null 2>&1 || { soleur_op_red "  jq not on PATH"; bad=1; }
  gh auth status >/dev/null 2>&1 \
    || { soleur_op_red "  gh is not authenticated (gh auth login)"; bad=1; }
  doppler secrets --only-names -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" >/dev/null 2>&1 \
    || { soleur_op_red "  cannot read ${DOPPLER_PROJECT}/${DOPPLER_CONFIG} (doppler login, or a dev-scoped token)"; bad=1; }
  [[ "$bad" -eq 0 ]] || return 1
  local cur_fp
  cur_fp="$(fp_of_secret "$DOPPLER_PROJECT" "$DOPPLER_CONFIG" GITHUB_APP_PRIVATE_KEY)"
  printf '  current dev_scheduled GITHUB_APP_PRIVATE_KEY fp: %s\n' "${cur_fp:-<none>}"
  printf '  expected dead-key fp (the #9995 failure):            8246898e\n'
  local inst; inst="$(installed_app)"
  if [[ -n "$inst" ]]; then
    soleur_op_yellow "  ${APP_SLUG} is already installed on ${ORG} (installation ${inst%% *})"
  else
    printf '  %s is not installed on %s yet.\n' "$APP_SLUG" "$ORG"
  fi
}

# =============================================================================
# create-app (write): browser-mediated. The founder's click creates the App; the
# ATTEMPTED marker (written before the page opens) makes an interrupted create
# visible instead of silently double-creating on re-run.
# =============================================================================
plan_create_app() {
  if [[ -n "$(installed_app)" ]]; then
    return 0  # installed: nothing to do
  fi
  if [[ -n "$(env_get APP_CREATE_ATTEMPTED)" ]]; then
    soleur_op_precondition_failed create-app record-key \
      "A previous run already opened the registration page. If the App exists, run stage record-key with SOLEUR_BOOTSTRAP_PEM_PATH set to the downloaded .pem; if the click never landed, run: bash ${SCRIPT_PATH} --reset APP_CREATE_ATTEMPTED"
  fi
  [[ -f "$MANIFEST_PAGE" ]] \
    || soleur_op_precondition_failed create-app preflight "the manifest launcher page ${MANIFEST_PAGE} is missing"
  soleur_op_plan_op register-github-app "${ORG}/${APP_SLUG}"
  soleur_op_plan_op generate-private-key "${ORG}/${APP_SLUG}"
}

apply_create_app() {
  mark_changed "the registration page was opened; the App may have been created"
  soleur_op_env_upsert "$ENV_FILE" APP_CREATE_ATTEMPTED "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
  printf '  A page will POST the manifest and open GitHub'"'"'s prefilled registration form.\n'
  printf '  1. Click "Create GitHub App".\n'
  printf '  2. On the new App page click "Generate a private key" — a .pem downloads.\n'
  printf '  3. Give the agent the .pem path (or move it under $XDG_RUNTIME_DIR first).\n'
  soleur_op_open_url "file://${MANIFEST_PAGE}"
}

# =============================================================================
# record-key (read at vendors): find the downloaded PEM, prove it is a private
# key, record path + fingerprint. The file itself is never printed.
# =============================================================================
read_record_key() {
  if [[ -n "$(env_get FIXTURE_PEM_FP)" && -n "$(env_get FIXTURE_PEM_PATH)" && -f "$(env_get FIXTURE_PEM_PATH)" ]]; then
    soleur_op_yellow "  already recorded: PEM fp $(env_get FIXTURE_PEM_FP) at $(env_get FIXTURE_PEM_PATH)"
    return 0
  fi
  local pem_path=""
  soleur_op_value SOLEUR_BOOTSTRAP_PEM_PATH "  Path of the downloaded .pem (move it under \$XDG_RUNTIME_DIR first): " pem_path
  [[ -f "$pem_path" ]] || { soleur_op_red "  no file at ${pem_path}"; return 1; }
  # `stat -f -c %T` is GNU-only; refuse non-Linux by name rather than misreading
  # a stat error as "not tmpfs".
  if [[ "$(uname -s 2>/dev/null)" != "Linux" ]]; then
    soleur_op_red "  record-key requires a tmpfs dir; this host is not Linux — run on a Linux host (macOS has no tmpfs)."
    return 1
  fi
  if [[ "$(stat -f -c %T "$(dirname "$pem_path")" 2>/dev/null)" != "tmpfs" ]]; then
    soleur_op_red "  ${pem_path} is not on tmpfs — move it under \$XDG_RUNTIME_DIR and re-run (a key must not sit in a disk-backed dir)."
    return 1
  fi
  chmod 600 -- "$pem_path"
  openssl pkey -check -in "$pem_path" -noout >/dev/null 2>&1 \
    || openssl rsa -check -in "$pem_path" -noout >/dev/null 2>&1 \
    || { soleur_op_red "  ${pem_path} is not a parseable private key"; return 1; }
  local fp; fp="$(fp_of_pem_file "$pem_path")"
  [[ -n "$fp" ]] || { soleur_op_red "  could not fingerprint ${pem_path}"; return 1; }
  printf '  downloaded key fingerprint: SHA256:%s\n' "$fp"
  soleur_op_env_upsert "$ENV_FILE" FIXTURE_PEM_PATH "$pem_path"
  soleur_op_env_upsert "$ENV_FILE" FIXTURE_PEM_FP "$fp"
  soleur_op_env_upsert "$ENV_FILE" FIXTURE_PEM_BYTES "$(wc -c <"$pem_path" | tr -d ' ')"
  soleur_op_env_reset "$ENV_FILE" APP_CREATE_ATTEMPTED
}

# =============================================================================
# install-app (write): open the install URL; the founder picks mu1-fixture only.
# Verified by the vendor's installations list, not by a local marker.
# =============================================================================
plan_install_app() {
  [[ -z "$(installed_app)" ]] || return 0  # already installed
  soleur_op_plan_op install-app "${ORG}/${APP_SLUG}->${ORG}/${FIXTURE_REPO} (only)"
}

apply_install_app() {
  local inst
  inst="$(installed_app)"
  if [[ -n "$inst" ]]; then
    printf '  already installed: installation %s (app_id %s)\n' "${inst%% *}" "${inst##* }"
    return 0
  fi
  mark_changed "the install page was opened; an installation may have been created"
  soleur_op_env_upsert "$ENV_FILE" INSTALL_OPENED "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
  printf '  On the install page: choose "Only select repositories" -> %s/%s, then Install.\n' "$ORG" "$FIXTURE_REPO"
  soleur_op_open_url "$INSTALL_URL"
  inst="$(installed_app)"
  if [[ -n "$inst" ]]; then
    printf '  installed: installation %s (app_id %s)\n' "${inst%% *}" "${inst##* }"
  else
    printf '  The installation is not visible yet — re-run this stage after clicking Install:\n'
    printf '  bash %s --stage install-app --apply --plan-digest <reprinted plan digest>\n' "$SCRIPT_PATH"
    return 1
  fi
}

# =============================================================================
# write-doppler (write): three dev_scheduled secrets + read-back proof + PEM rm.
# =============================================================================
plan_write_doppler() {
  local pem_fp; pem_fp="$(env_get FIXTURE_PEM_FP)"
  [[ -n "$pem_fp" && -f "$(env_get FIXTURE_PEM_PATH)" ]] \
    || soleur_op_precondition_failed write-doppler record-key "no verified .pem is recorded yet"
  local inst; inst="$(installed_app)"
  [[ -n "$inst" ]] \
    || soleur_op_precondition_failed write-doppler install-app "${APP_SLUG} is not installed on ${ORG} yet"
  local iid="${inst%% *}" aid="${inst##* }"
  # satisfied check: every stored value already equals the vendor/PEM truth
  local ok_id ok_key ok_iid
  [[ "$(doppler secrets get GITHUB_APP_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --plain 2>/dev/null)" == "$aid" ]] && ok_id=1 || ok_id=0
  [[ "$(fp_of_secret "$DOPPLER_PROJECT" "$DOPPLER_CONFIG" GITHUB_APP_PRIVATE_KEY)" == "$pem_fp" ]] && ok_key=1 || ok_key=0
  [[ "$(doppler secrets get MU1_FIXTURE_INSTALLATION_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --plain 2>/dev/null)" == "$iid" ]] && ok_iid=1 || ok_iid=0
  if [[ "$ok_id" == 1 && "$ok_key" == 1 && "$ok_iid" == 1 ]]; then return 0; fi
  [[ "$ok_id" == 1 ]]  || soleur_op_plan_op set-secret "GITHUB_APP_ID@${DOPPLER_PROJECT}/${DOPPLER_CONFIG}"
  [[ "$ok_key" == 1 ]] || soleur_op_plan_op set-secret "GITHUB_APP_PRIVATE_KEY@${DOPPLER_PROJECT}/${DOPPLER_CONFIG}"
  [[ "$ok_iid" == 1 ]] || soleur_op_plan_op set-secret "MU1_FIXTURE_INSTALLATION_ID@${DOPPLER_PROJECT}/${DOPPLER_CONFIG}"
  soleur_op_plan_op delete-pem-file "$(env_get FIXTURE_PEM_PATH)"
}

apply_write_doppler() {
  local pem_path pem_fp inst iid aid set_rc=0
  pem_path="$(env_get FIXTURE_PEM_PATH)"; pem_fp="$(env_get FIXTURE_PEM_FP)"
  # Re-prove everything in THIS process — the plan ran in a previous one, and a
  # hand-edited .env or a removed install must never write empty strings.
  [[ -n "$pem_fp" && -f "$pem_path" ]] \
    || { soleur_op_red "  no verified .pem recorded — run record-key first"; return 1; }
  inst="$(installed_app)"
  [[ -n "$inst" ]] \
    || { soleur_op_red "  ${APP_SLUG} installation not visible — aborting before any write (re-run install-app)"; return 1; }
  iid="${inst%% *}"; aid="${inst##* }"
  mark_changed "dev_scheduled GITHUB_APP_* and MU1_FIXTURE_INSTALLATION_ID may have been rewritten"
  printf '%s' "$aid" | doppler secrets set GITHUB_APP_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --silent >/dev/null || set_rc=$?
  doppler secrets set GITHUB_APP_PRIVATE_KEY -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --silent <"$pem_path" >/dev/null || set_rc=$?
  printf '%s' "$iid" | doppler secrets set MU1_FIXTURE_INSTALLATION_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --silent >/dev/null || set_rc=$?
  if [[ "$set_rc" -ne 0 ]]; then
    soleur_op_red "  a Doppler write returned rc=${set_rc}; the PEM is KEPT at ${pem_path}"
    return 1
  fi
  local back_fp back_aid back_iid
  back_fp="$(fp_of_secret "$DOPPLER_PROJECT" "$DOPPLER_CONFIG" GITHUB_APP_PRIVATE_KEY)"
  back_aid="$(doppler secrets get GITHUB_APP_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --plain 2>/dev/null)"
  back_iid="$(doppler secrets get MU1_FIXTURE_INSTALLATION_ID -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" --plain 2>/dev/null)"
  if [[ "$back_fp" != "$pem_fp" || "$back_aid" != "$aid" || "$back_iid" != "$iid" ]]; then
    soleur_op_red "  read-back mismatch (key fp ${back_fp:-none} vs ${pem_fp}); the PEM is KEPT at ${pem_path}"
    return 1
  fi
  rm -f -- "$pem_path"
  [[ ! -e "$pem_path" ]] || { soleur_op_red "  could not delete ${pem_path} — remove it by hand"; return 1; }
  soleur_op_env_upsert "$ENV_FILE" FIXTURE_APP_ID "$aid"
  soleur_op_env_upsert "$ENV_FILE" FIXTURE_INSTALLATION_ID "$iid"
  soleur_op_env_upsert "$ENV_FILE" DOPPLER_WRITTEN "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
  printf '  stored: GITHUB_APP_ID=%s MU1_FIXTURE_INSTALLATION_ID=%s key fp=%s (%s bytes)\n' \
    "$aid" "$iid" "$pem_fp" "$(env_get FIXTURE_PEM_BYTES)"
  printf '  PEM deleted. Clear the browser'"'"'s download history for that file.\n'
}

# =============================================================================
# verify (read): the live mint probe under the new dev_scheduled values.
# =============================================================================
read_verify() {
  if [[ -z "$(env_get DOPPLER_WRITTEN)" ]]; then
    soleur_op_red "  the write-doppler stage has not completed — run it first"
    return 1
  fi
  local repo_root; repo_root="$(cd "$SCRIPT_DIR/../../../.." && pwd)"
  local out rc=0
  out="$(cd "$repo_root" && doppler run -p "$DOPPLER_PROJECT" -c "$DOPPLER_CONFIG" -- \
    bash scripts/probe-github-app-mint.sh 2>&1)" || rc=$?
  printf '%s\n' "$out"
  if [[ "$rc" -ne 0 || "$out" != *"GITHUB_APP_MINT status=200 slug=${APP_SLUG}"* ]]; then
    soleur_op_red "  mint probe did not report slug=${APP_SLUG} status=200"
    return 1
  fi
  soleur_op_green "  verified: ${APP_SLUG} mints a live JWT under dev_scheduled"
}

# --- the dispatcher: one stage per invocation --------------------------------
# Not a stage: the one place that applies the staged contract. A stage function
# never gates itself and never prints a stage marker (a marker printed inside a
# `$(...)` capture becomes the captured value).
dispatch_stage() {
  local stage="$1" class fn impact rollback flags="" n
  if ! class="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 2)"; then
    printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
    printf 'That stage is not declared by this script. The stages are:\n'
    soleur_op_list "${BASH_SOURCE[0]}"
    exit 64
  fi
  fn="${stage//-/_}"
  CURRENT_STAGE_INDEX=1; CURRENT_STAGE_NAME="$stage"; STAGE_CHANGED=""
  soleur_op_stage_begin 1 "$stage"
  case "$class" in
    read)
      "read_${fn}"
      soleur_op_stage_ok "$stage" 0
      ;;
    write)
      impact="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 3)"
      rollback="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 4)"
      [[ "$ROTATE_TOKEN" == "1" ]] && flags="rotate-token"
      soleur_op_plan_begin
      "plan_${fn}"
      n="$(soleur_op_plan_count)"
      if [[ "$APPLY" -ne 1 ]]; then
        soleur_op_plan_emit "$SCRIPT_REAL" "$stage" "$ROTATE_TOKEN"
        if [[ "$n" -eq 0 ]]; then soleur_op_stage_ok "$stage" 0; fi
      elif [[ "$n" -eq 0 ]]; then
        soleur_op_stage_ok "$stage" 0
      else
        if [[ -z "$PLAN_DIGEST" ]]; then
          printf 'SOLEUR_BOOTSTRAP_PLAN_DIGEST_REQUIRED stage=%s\n' "$stage"
          printf 'Run the stage without --apply first, then run the apply command exactly as the plan printed it.\n'
          SOLEUR_OP_REFUSED=1
          exit 64
        fi
        local computed
        computed="$(soleur_op_plan_digest "$SCRIPT_REAL" "$stage" "$flags" "$impact" "$rollback")"
        soleur_op_stage_gate "$SCRIPT_REAL" "$stage" "$computed" "$PLAN_DIGEST" "$impact" "$rollback" "${ORIG_ARGV[@]}"
        "apply_${fn}"
        soleur_op_stage_ok "$stage" 1 "$SOLEUR_OP_APPROVAL"
      fi
      ;;
    *)
      printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
      exit 64
      ;;
  esac
  soleur_op_stage_end 1 "$stage" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""; STAGE_CHANGED=""
}

main() {
  soleur_op_require_bins grep mktemp printenv sed date od id stat cut tr awk find gh doppler openssl jq
  soleur_op_ledger_init 1 "bootstrap.sh"
  dispatch_stage "$STAGE"
}

main "$@"
